import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.Cz0TtJv6.js";const k=JSON.parse('{"title":"API keys","description":"Helius RPC, Jupiter, and GMGN — where to sign up, how to copy keys into the dashboard wizard or Settings.","frontmatter":{"title":"API keys","description":"Helius RPC, Jupiter, and GMGN — where to sign up, how to copy keys into the dashboard wizard or Settings."},"headers":[],"relativePath":"api-keys.md","filePath":"api-keys.md","lastUpdated":1786732488000}'),n={name:"api-keys.md"};function r(o,e,l,p,h,d){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="api-keys" tabindex="-1">API keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API keys&quot;">​</a></h1><p>Paste these in the first-run <strong>setup wizard</strong> or <strong>Settings → Wallet &amp; secrets</strong> (writes to <code>data/.env</code> on your volume).</p><table tabindex="0"><thead><tr><th>Key</th><th>Required?</th><th>Free tier?</th><th>What it powers</th></tr></thead><tbody><tr><td><strong><code>RPC_URL</code></strong> (Helius)</td><td><strong>Yes</strong></td><td>Yes (signup)</td><td>On-chain reads, vetting, tx simulation</td></tr><tr><td><strong><code>JUPITER_API_KEY</code></strong></td><td><strong>Yes</strong> before live</td><td>Yes</td><td>Exit swaps (token → SOL), profit-burn, <code>simulate-zap</code></td></tr><tr><td><strong><code>GMGN_API_KEY</code></strong></td><td>Optional (recommended)</td><td>Yes</td><td>Trending discovery, smart-money feeds, honeypot/sell-tax vetting</td></tr></tbody></table><p>Without GMGN the bot still runs on Meteora datapi + RPC + RugCheck — GMGN adds score bonuses (capped at +10) and extra security flags.</p><h2 id="helius-rpc-rpc-url" tabindex="-1">Helius RPC (<code>RPC_URL</code>) <a class="header-anchor" href="#helius-rpc-rpc-url" aria-label="Permalink to &quot;Helius RPC (`RPC_URL`)&quot;">​</a></h2><p>Public RPC works for a smoke test. Live needs a private endpoint.</p><p class="cta-row"><a class="doc-btn" href="https://dashboard.helius.dev/signup" target="_blank" rel="noreferrer">Sign up at Helius</a><a class="doc-btn ghost" href="https://www.helius.dev/docs/api-reference/endpoints" target="_blank" rel="noreferrer">Endpoint docs</a></p><ol><li>Create a project → <strong>RPC</strong> → copy the <strong>Mainnet</strong> HTTPS URL</li><li>Paste into the wizard or <code>RPC_URL</code> in Settings / <code>.env</code></li></ol><p>Example: <code>https://mainnet.helius-rpc.com/?api-key=YOUR_KEY</code></p><h2 id="jupiter-api-key-jupiter-api-key" tabindex="-1">Jupiter API key (<code>JUPITER_API_KEY</code>) <a class="header-anchor" href="#jupiter-api-key-jupiter-api-key" aria-label="Permalink to &quot;Jupiter API key (`JUPITER_API_KEY`)&quot;">​</a></h2><p>Live exits route through Jupiter. Paper simulates fills, but you still want a key for <code>npm run simulate-zap</code> before going live.</p><p class="cta-row"><a class="doc-btn" href="https://developers.jup.ag/portal" target="_blank" rel="noreferrer">Jupiter Portal</a><a class="doc-btn ghost" href="https://developers.jup.ag/docs/portal/setup" target="_blank" rel="noreferrer">Setup guide</a></p><ol><li>Sign in (Google, GitHub, or email)</li><li>Create or join a <strong>team</strong></li><li><strong>API Keys → Create</strong> — name it (e.g. <code>dlmmbot-prod</code>)</li><li>Copy the key <strong>immediately</strong> — Jupiter shows the full value once</li><li>Paste into the wizard or <code>JUPITER_API_KEY</code></li></ol><p>Free tier (1 req/s) is enough to start.</p><h2 id="gmgn-api-key-gmgn-api-key-—-optional" tabindex="-1">GMGN API key (<code>GMGN_API_KEY</code>) — optional <a class="header-anchor" href="#gmgn-api-key-gmgn-api-key-—-optional" aria-label="Permalink to &quot;GMGN API key (`GMGN_API_KEY`) — optional&quot;">​</a></h2><p>Query-only trending + honeypot/sell-tax checks. The bot never trades through GMGN, so you do <strong>not</strong> need <code>GMGN_PRIVATE_KEY</code>.</p><p class="cta-row"><a class="doc-btn" href="https://gmgn.ai/ai" target="_blank" rel="noreferrer">Open GMGN</a><a class="doc-btn ghost" href="https://docs.gmgn.ai/index/generate-public-key" target="_blank" rel="noreferrer">Generate a public key</a></p><h3 id="_1-generate-a-key-pair-ed25519" tabindex="-1">1. Generate a key pair (Ed25519) <a class="header-anchor" href="#_1-generate-a-key-pair-ed25519" aria-label="Permalink to &quot;1. Generate a key pair (Ed25519)&quot;">​</a></h3><p><strong>Terminal (Linux / macOS / WSL / VPS):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> genpkey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -algorithm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmgn_private.pem</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmgn_private.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pubout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmgn_public.pem</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmgn_public.pem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # copy this whole block for step 2</span></span></code></pre></div><p>Keep <code>gmgn_private.pem</code> off the bot. <strong>GUI:</strong> GMGN’s key-generator app → <strong>Generate 1 Key Pair</strong> → copy the <strong>public</strong> key.</p><p class="note warn">Paste the entire public key, including the <code>BEGIN</code> / <code>END PUBLIC KEY</code> lines, into GMGN’s form.</p><h3 id="_2-create-the-api-key-on-gmgn" tabindex="-1">2. Create the API key on GMGN <a class="header-anchor" href="#_2-create-the-api-key-on-gmgn" aria-label="Permalink to &quot;2. Create the API key on GMGN&quot;">​</a></h3><ol><li>Sign up at <a href="https://gmgn.ai/ai" target="_blank" rel="noreferrer">gmgn.ai/ai</a></li><li>Open the <strong>API key</strong> panel</li><li>Paste your <strong>public</strong> key → copy the <strong>API Key</strong> GMGN shows you</li><li>Paste that value as <code>GMGN_API_KEY</code></li></ol><p>Rate limit: GMGN’s query API uses a leaky bucket (<code>rate=10</code> / <code>capacity=10</code>, heavier weight on holders/traders) and documents ~1 req/s. The farmer runs <strong>one serial CLI queue</strong>, waits for each call to finish before the next, honors <code>X-RateLimit-Reset</code> / <code>reset_at</code> on 429 (never spam the cooldown — that extends bans), and degrades to Meteora-only data while cooling down.</p><h2 id="quick-copy-checklist" tabindex="-1">Quick copy checklist <a class="header-anchor" href="#quick-copy-checklist" aria-label="Permalink to &quot;Quick copy checklist&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># data/.env (or wizard / Settings)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RPC_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://mainnet.helius-rpc.com/?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api-key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YOUR_HELIUS_KEY</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JUPITER_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_jupiter_key</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GMGN_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_gmgn_key</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # optional</span></span></code></pre></div><p class="cta-row"><a class="doc-btn ghost" href="./easy">Easy setup</a><a class="doc-btn ghost" href="./advanced">Advanced setup</a><a class="doc-btn ghost" href="./configuration">Configuration</a></p>',28)])])}const g=t(n,[["render",r]]);export{k as __pageData,g as default};
